def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    delta = {2: -1, 5: +1}   # 2 shrinks, 5 grows; other colours stay

    def ring(cy, cx, r):
        cells = set()
        if r < 0:
            return cells
        for y in range(H):
            d = r - abs(y - cy)
            if d < 0:
                continue
            for x in (cx - d, cx + d):
                if 0 <= x < W:
                    cells.add((y, x))
        return cells

    def fit(cells):
        cs = set(cells)
        best = None
        y0, x0 = cells[0]
        for cy in range(-H, 2 * H):
            for cx in range(-W, 2 * W):
                r = abs(y0 - cy) + abs(x0 - cx)
                if best is not None and r >= best[2]:
                    continue
                if any(abs(y - cy) + abs(x - cx) != r for y, x in cells):
                    continue
                if ring(cy, cx, r) == cs:
                    best = (cy, cx, r)
        return best

    shapes = []
    for col, dr in delta.items():
        for comp in components(g == col, diagonal=True):
            f = fit(comp)
            if f is None:
                continue
            shapes.append((col, dr, comp, f))

    out = g.copy()
    for col, dr, comp, f in shapes:
        for y, x in comp:
            out[y, x] = bg
    emit(out, "Erase every colour-2 diamond (they shrink) and colour-5 diamond (they grow); 8/9 shapes stay.")

    for col, dr, comp, (cy, cx, r) in shapes:
        nr = r + dr
        ncx = cx
        if dr > 0 and cy == H - 1:
            ncx = cx + 1   # observed placement for a growing ring centred on the bottom edge
        for y, x in ring(cy, ncx, nr):
            out[y, x] = col
        emit(out, f"Redraw colour-{col} diamond centred ({cy},{cx}) with radius {r} -> {nr}.")

    emit(out, "Final grid.")
    return out
